{
  "measurement_needs": [
    "Rheological behavior of the polymer as a function of temperature and shear rate",
    "Thermal stability, degradation temperature, and composition of the polymer"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ21",
      "role": "primary",
      "technique": "Rotational and oscillatory rheometry",
      "why": "This hybrid rheometer includes an Environmental Test Chamber, allowing you to measure melt viscosity, shear-thinning behavior, and viscoelastic properties across the elevated temperatures relevant to your extrusion process.",
      "accessories_to_confirm": [
        "Parallel plate or cone-and-plate geometries suitable for polymer melts"
      ]
    },
    {
      "instrument_id": "EQ17",
      "role": "supplementary",
      "technique": "Thermogravimetric Analysis (TGA)",
      "why": "TGA measures sample mass loss as a function of temperature, helping you determine if thermal degradation, crosslinking, or volatilization is occurring at your extrusion temperatures.",
      "accessories_to_confirm": [
        "Standard platinum sample pans and purge gas selection (e.g., nitrogen or air)"
      ]
    },
    {
      "instrument_id": "EQ18",
      "role": "supplementary",
      "technique": "Differential Scanning Calorimetry (DSC)",
      "why": "DSC can identify thermal transitions such as melting points, glass transition temperatures, or premature curing/crosslinking that could cause unexpected viscosity increases during heating.",
      "accessories_to_confirm": [
        "Tzero aluminum pans and hermetic lids"
      ]
    }
  ],
  "not_available": [],
  "clarifying_question": null,
  "summary": "To understand why your polymer remains unexpectedly viscous, you need to characterize its flow properties and thermal profile. The hybrid rheometer (EQ21) can directly measure melt viscosity across your extrusion temperatures using its environmental chamber. Additionally, TGA (EQ17) and DSC (EQ18) can provide supplementary insights into thermal stability and phase transitions."
}

