{
  "measurement_needs": [
    "cell viability within 3D hydrogels",
    "cell morphology and spreading within 3D hydrogels"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ07",
      "role": "primary",
      "technique": "Laser scanning confocal microscopy",
      "why": "The inverted confocal microscope provides optical sectioning required to image fluorescence-stained live/dead cells deep within 3D hydrogel constructs without excessive out-of-focus blur.",
      "accessories_to_confirm": [
        "appropriate fluorescence filter sets or laser lines for live/dead assay stains (e.g., calcein-AM and ethidium homodimer)",
        "chamber slide or multi-well plate holders compatible with hydrogels"
      ]
    },
    {
      "instrument_id": "EQ08",
      "role": "primary",
      "technique": "Multiphoton confocal microscopy",
      "why": "The upright multiphoton microscope uses longer wavelength excitation, which improves imaging depth and reduces phototoxicity when evaluating thicker 3D hydrogel samples.",
      "accessories_to_confirm": [
        "appropriate objectives with long working distances",
        "live-cell incubation stage top chamber if imaging needs to be maintained at physiological conditions"
      ]
    },
    {
      "instrument_id": "EQ09",
      "role": "supplementary",
      "technique": "High-content epifluorescence imaging",
      "why": "Can provide automated multi-well screening of viability and spreading, though it lacks the optical sectioning capability of a confocal microscope for thick 3D structures.",
      "accessories_to_confirm": [
        "appropriate fluorescence filter cubes",
        "multi-well plates for hydrogel casting"
      ]
    }
  ],
  "not_available": [],
  "clarifying_question": null,
  "summary": "To check whether cells are alive and spreading inside a 3D hydrogel, you can fluorescently stain the hydrogel constructs (e.g., using a live/dead viability assay and a cytoskeletal stain for morphology) and image them using laser scanning or multiphoton confocal microscopy. Both the inverted confocal microscope (EQ07) and upright multiphoton microscope (EQ08) can perform optical sectioning deep into 3D constructs to visualize cell viability and spreading. High-content epifluorescence imaging (EQ09) can serve as a supplementary tool for broader screening."
}

